let week=0,resourceFilter='全部',search='',studioRole=state.role||'admin',wizardStep=0,draft=null,toastTimer;
function persist(){if(!state.save)return;try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('浏览器未能保存，请及时导出记录。');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function roleById(id){return ROLES.find(r=>r.id===id)||ROLES[0];}
function candidates(p){const adjacent={admin:['hr','support','supply'],hr:['admin','support','sales'],finance:['supply','admin','insurance'],support:['sales','admin','service'],content:['sales','support','admin'],sales:['support','content','service'],education:['content','admin','support'],health:['admin','service','support'],supply:['finance','admin','sales'],insurance:['finance','sales','support'],service:['support','sales','admin']};return ROLES.filter(r=>r.id===p.role||!['health','education','insurance'].includes(r.id)).map((r,i)=>{let n=(p.role===r.id?15:0)+r.skills.filter(s=>p.skills.includes(s)).length*2;if(adjacent[p.role]?.includes(r.id))n+=5;if(p.path==='B'&&r.entry)n+=4;if((p.path==='C'||p.arrangement==='优先居家'||p.arrangement==='弹性或兼职')&&r.flex)n+=3;return {r,n,i};}).sort((a,b)=>b.n-a.n||a.i-b.i).slice(0,3).map(x=>x.r);}
function defaultProfile(path='A'){return {path,role:'admin',break:'1—3年',skills:[],experience:'',minutes:30,chunk:20,arrangement:'不限',goal:'恢复原职业能力',horizon:'1—3个月',city:'广州',concerns:[]};}
